INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7373072, 1156942, 121949, '<td valign="top"><strike></strike></td>', '', '2015-06-26 01:11:34.000000', NULL, 1),
(7373075, 1156144, 30982, '<td valign="top">I love the sparkle in her eyes!  But I''m not overly fond of the forced blur.  Still a very cute picture of a VERY cute girl!</td>', 'I love the sparkle in her eyes!  But I''m not overly fond of the forced blur.  Still a very cute picture of a VERY cute girl!', '2015-06-26 01:14:05.000000', NULL, 1),
(7373076, 1156969, 30982, '<td valign="top">Ummm.  Wow.  That''s pretty darn spectacular.</td>', 'Ummm.  Wow.  That''s pretty darn spectacular.', '2015-06-26 01:14:27.000000', NULL, 1),
(7373077, 1155974, 30982, '<td valign="top">Very classically you, Anita.</td>', 'Very classically you, Anita.', '2015-06-26 01:14:41.000000', NULL, 1),
(7373079, 1156858, 30861, '<td valign="top">Nobody does "weirdo" like you do weirdo :-) Popped right off the thumbs page at me, first vote for me and a 10. The larger bird''s so damned intense...</td>', 'Nobody does "weirdo" like you do weirdo :-) Popped right off the thumbs page at me, first vote for me and a 10. The larger bird''s so damned intense...', '2015-06-26 01:15:11.000000', NULL, 1),
(7373080, 1157027, 30982, '<td valign="top">Quite lovely and peaceful!</td>', 'Quite lovely and peaceful!', '2015-06-26 01:15:15.000000', NULL, 1),
(7373081, 1156730, 30982, '<td valign="top">Oh, I love this.  Didn''t even look at the author.  Spectacular B&amp;W and a really good crop.</td>', 'Oh, I love this.  Didn''t even look at the author.  Spectacular B&W and a really good crop.', '2015-06-26 01:15:46.000000', NULL, 1),
(7373082, 1156967, 30982, '<td valign="top">Ha! Don''t know that I''d associate you with Legos, but if you say so!</td>', 'Ha! Don''t know that I''d associate you with Legos, but if you say so!', '2015-06-26 01:16:32.000000', NULL, 1),
(7373084, 1155814, 30982, '<td valign="top">What a bizzarro creature!  And I gotta say, it''s been awesome watching you grow here at DPC - keep it up!</td>', 'What a bizzarro creature!  And I gotta say, it''s been awesome watching you grow here at DPC - keep it up!', '2015-06-26 01:17:23.000000', NULL, 1),
(7373085, 1155514, 30982, '<td valign="top">Ha!  I''ve been playing "Guess the photog" - this one was easy!  I like the light falling out of the window best.</td>', 'Ha!  I''ve been playing "Guess the photog" - this one was easy!  I like the light falling out of the window best.', '2015-06-26 01:18:02.000000', NULL, 1),
(7373087, 1156965, 30982, '<td valign="top">Awesome contrast.  Though I didn''t guess you (I''m guessing as I go), this fits well - the wonderful eye for patterns and the crisp monochrome.</td>', 'Awesome contrast.  Though I didn''t guess you (I''m guessing as I go), this fits well - the wonderful eye for patterns and the crisp monochrome.', '2015-06-26 01:20:00.000000', NULL, 1),
(7373099, 1155213, 30982, '<td valign="top">A nice tenderness to this.  The overlay suits.</td>', 'A nice tenderness to this.  The overlay suits.', '2015-06-26 01:30:24.000000', NULL, 1),
(7373101, 1155699, 30982, '<td valign="top">I love the stark contrast of the shadows.  A rather non-standard photograph, but a fascinating one to me just the same.</td>', 'I love the stark contrast of the shadows.  A rather non-standard photograph, but a fascinating one to me just the same.', '2015-06-26 01:30:58.000000', NULL, 1),
(7373102, 1156730, 100831, '<td valign="top">My fave,. the group that is. PUNCH BROTHERS... the image is fab too.</td>', 'My fave,. the group that is. PUNCH BROTHERS... the image is fab too.', '2015-06-26 01:32:17.000000', NULL, 1),
(7373104, 1157024, 30982, '<td valign="top">Ha!  This really does suit you!  Strong and bold with not your run of the mill processing.  Nicely done!</td>', 'Ha!  This really does suit you!  Strong and bold with not your run of the mill processing.  Nicely done!', '2015-06-26 01:33:37.000000', NULL, 1),
(7373105, 1155064, 30982, '<td valign="top">Heh!  I''ve seen this little guy on your Facebook page.  Your landscapes are amazing, but I really enjoy when you share your wildlife photography with us.</td>', 'Heh!  I''ve seen this little guy on your Facebook page.  Your landscapes are amazing, but I really enjoy when you share your wildlife photography with us.', '2015-06-26 01:34:51.000000', NULL, 1),
(7373106, 1157016, 30982, '<td valign="top">I guess you do like birds!  Lovely detail on this chicken.</td>', 'I guess you do like birds!  Lovely detail on this chicken.', '2015-06-26 01:35:45.000000', NULL, 1),
(7373108, 1156981, 30982, '<td valign="top">Very energetic!  I''ve enjoyed your blurry trees.</td>', 'Very energetic!  I''ve enjoyed your blurry trees.', '2015-06-26 01:36:58.000000', NULL, 1),
(7373109, 1156881, 30982, '<td valign="top">Tibi, you always have such humanity in your photographys.  You seem to be there yet not, in that rarely do you intrude with your camera.  I''m always in awe of your work and so very glad you share it with us!</td>', 'Tibi, you always have such humanity in your photographys.  You seem to be there yet not, in that rarely do you intrude with your camera.  I''m always in awe of your work and so very glad you share it with us!', '2015-06-26 01:37:57.000000', NULL, 1),
(7373111, 1155438, 96751, '<td valign="top">This is my favorite image of anything you''ve posted on DPC. Just splendid.</td>', 'This is my favorite image of anything you''ve posted on DPC. Just splendid.', '2015-06-26 01:38:57.000000', NULL, 1),
(7373113, 1155334, 96751, '<td valign="top">Nice catch ;)</td>', 'Nice catch ;)', '2015-06-26 01:39:54.000000', NULL, 1),
(7373114, 1155377, 96751, '<td valign="top">People with cats should have a scoring handicap...</td>', 'People with cats should have a scoring handicap...', '2015-06-26 01:40:29.000000', NULL, 1),
(7373115, 1156969, 96751, '<td valign="top">Really splendid, Ale. Love that sky</td>', 'Really splendid, Ale. Love that sky', '2015-06-26 01:40:46.000000', NULL, 1),
(7373116, 1156933, 96751, '<td valign="top">Classic</td>', 'Classic', '2015-06-26 01:42:13.000000', NULL, 1),
(7373121, 1157031, 30982, '<td valign="top">Creates a nice silhouette against that orange sky.  The outline is just a bit soft.</td>', 'Creates a nice silhouette against that orange sky.  The outline is just a bit soft.', '2015-06-26 01:49:32.000000', NULL, 1),
(7373122, 1156914, 30982, '<td valign="top">Perhaps not as abstract as some of your work, but still clearly within your wheelhouse, and given the stories you''ve been telling of your adventures, a wonderful souvenir of your vacation!</td>', 'Perhaps not as abstract as some of your work, but still clearly within your wheelhouse, and given the stories you''ve been telling of your adventures, a wonderful souvenir of your vacation!', '2015-06-26 01:51:13.000000', NULL, 1),
(7373125, 1156164, 30982, '<td valign="top">Ha!  Guessed this one immediately.  Clean, crisp, photograph, well composed.  And it has a bike.  :-)  Nicely done.</td>', 'Ha!  Guessed this one immediately.  Clean, crisp, photograph, well composed.  And it has a bike.  :-)  Nicely done.', '2015-06-26 01:52:08.000000', NULL, 1),
(7373128, 1156477, 30982, '<td valign="top">You do seem to enjoy design and pattern - this is nicely abstractish.  It doesn''t seem quite up to your usual standards, though - a bit soft due to possibly to camera movement, perhaps?  Your Oil and Ink, shot for instance, is much brighter, crisper, cleaner (and an amazing photograph!)</td>', 'You do seem to enjoy design and pattern - this is nicely abstractish.  It doesn''t seem quite up to your usual standards, though - a bit soft due to possibly to camera movement, perhaps?  Your Oil and Ink, shot for instance, is much brighter, crisper, cleaner (and an amazing photograph!)', '2015-06-26 01:55:24.000000', NULL, 1),
(7373129, 1156784, 30982, '<td valign="top">Really.  I''d never have guessed it was you.... (ha!)</td>', 'Really.  I''d never have guessed it was you.... (ha!)', '2015-06-26 01:55:38.000000', NULL, 1),
(7373131, 1156987, 30982, '<td valign="top">You do tend to find people who lack the happy sometimes.  But perhaps they''re just a bit tired from a hard day of play.  What I do like is you always find something with a bit of a story to be had.  Your train rides are a gold mine.</td>', 'You do tend to find people who lack the happy sometimes.  But perhaps they''re just a bit tired from a hard day of play.  What I do like is you always find something with a bit of a story to be had.  Your train rides are a gold mine.', '2015-06-26 01:56:52.000000', NULL, 1),
(7373132, 1156918, 30982, '<td valign="top">This is joyful and adorable!!</td>', 'This is joyful and adorable!!', '2015-06-26 01:57:07.000000', NULL, 1),
(7373133, 1156873, 30982, '<td valign="top">I trust this is one of yours?  It sings - definitely a keeper.</td>', 'I trust this is one of yours?  It sings - definitely a keeper.', '2015-06-26 01:58:06.000000', NULL, 1),
(7373134, 1157022, 30982, '<td valign="top">I knew that head of hair immediately.  This encapsulates a lot of what I see in your photography - your willingness to be less than conventional, and mostly the way you manage to harness light.  You just can''t create that in Photoshop.</td>', 'I knew that head of hair immediately.  This encapsulates a lot of what I see in your photography - your willingness to be less than conventional, and mostly the way you manage to harness light.  You just can''t create that in Photoshop.', '2015-06-26 01:59:34.000000', NULL, 1),
(7373135, 1156674, 30982, '<td valign="top">A very good hair day!  Lovely light through the feathers.  (The squirrels were on strike, eh?)  :-)</td>', 'A very good hair day!  Lovely light through the feathers.  (The squirrels were on strike, eh?)  :-)', '2015-06-26 02:00:15.000000', NULL, 1),
(7373156, 1157009, 43191, '<td valign="top">gorgeous :)</td>', 'gorgeous :)', '2015-06-26 03:32:15.000000', NULL, 1),
