(7373168, 1157033, 180155, '<td valign="top">Very good composition and good catch. I like it. Well done!</td>', 'Very good composition and good catch. I like it. Well done!', '2015-06-26 05:01:41.000000', NULL, 1),
(7373169, 1156038, 180155, '<td valign="top">I like the natural look. Good work!</td>', 'I like the natural look. Good work!', '2015-06-26 05:02:14.000000', NULL, 1),
(7373170, 1156987, 180155, '<td valign="top">The looks on their faces are so striking. I wondered what they were thinking really. Well done!</td>', 'The looks on their faces are so striking. I wondered what they were thinking really. Well done!', '2015-06-26 05:04:40.000000', NULL, 1),
(7373171, 1156941, 180155, '<td valign="top">I love the colors. Such an illuminating image with a graphic look in the background. Well done!</td>', 'I love the colors. Such an illuminating image with a graphic look in the background. Well done!', '2015-06-26 05:05:39.000000', NULL, 1),
(7373183, 1156969, 49109, '<td valign="top">Just hoping you enter sth like this for ROT :)</td>', 'Just hoping you enter sth like this for ROT :)', '2015-06-26 06:42:17.000000', NULL, 1),
(7373184, 1156836, 49109, '<td valign="top">What a waste! This could have ribboned in "feathers"</td>', 'What a waste! This could have ribboned in "feathers"', '2015-06-26 06:44:03.000000', NULL, 1),
(7373202, 1156877, 75618, '<td valign="top">I like this lovely light and foreground, I just wish the transition from blur to sharp wasn''t so abrupt. Or maybe that''s the point. 7</td>', 'I like this lovely light and foreground, I just wish the transition from blur to sharp wasn''t so abrupt. Or maybe that''s the point. 7', '2015-06-26 07:26:15.000000', NULL, 1),
