(7379748, 1155284, 67697, '<td valign="top">This is definitely a "you" kind of shot.  I love seeing the kids grow up DPC.</td>', 'This is definitely a "you" kind of shot.  I love seeing the kids grow up DPC.', '2015-07-02 01:49:20.000000', NULL, 1),
(7379750, 1156914, 67697, '<td valign="top">The silhouettes give me the impression of a quartet ready to play some music.  That evening sky is gorgeous.</td>', 'The silhouettes give me the impression of a quartet ready to play some music.  That evening sky is gorgeous.', '2015-07-02 01:50:06.000000', NULL, 1),
